draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw stick figure
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // Draw atomic habits circle
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 50, 30 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();

  // Draw identity circle
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 100, 30 + 10 * Math.cos(t), 0, 2 * Math.PI);
  ctx.stroke();

  // Draw change arrow
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 150);
  ctx.lineTo(W/2, H/2 - 120 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 120 + 20 * Math.sin(t));
  ctx.lineTo(W/2 - 10, H/2 - 100 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 120 + 20 * Math.sin(t));
  ctx.lineTo(W/2 + 10, H/2 - 100 + 20 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
